import{z as s,x as i,o,c as p,q as t,j as A,D as e,d as B,s as r,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"PSRO 与对手池","description":"","frontmatter":{"title":"PSRO 与对手池","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sgt-psro-opponent-pool.md","filePath":"llm/sgt-psro-opponent-pool.md","lastUpdated":1791063341000}'),d={name:"llm/sgt-psro-opponent-pool.md"};function D(m,E,C,F,h,c){const l=i("Mermaid");return o(),p("div",null,[E[2]||(E[2]=t('<h1 id="psro-与对手池" tabindex="-1">PSRO 与对手池 <a class="header-anchor" href="#psro-与对手池" aria-label="Permalink to &quot;PSRO 与对手池&quot;">​</a></h1><div class="epigraph"><p>自博弈的对手池不是经验收集器，而是一张策略元博弈的坐标表：每加一个对手，就补上策略空间一块还没被利用的盲区。</p><footer>—— 据 Lanctot et al., A Unified Game-Theoretic Approach to Multiagent RL, 2017 整理</footer></div><p><a href="/llm/sgt-fictitious-play">上一课</a>把 FSP 的骨架拆开：对对手的<strong>分布</strong>做最优响应，收敛因此有据。但它留了一个递归问题——那个分布从哪来？FSP 用历史频率答，PSRO（policy-space response oracle）用显式的元博弈均衡答。本课讲 PSRO 的循环与对手池的构造法，它是 AlphaStar 联赛训练与各类「自博弈对手池」工程的共同祖先；主干课讲过的<a href="/llm/player-selection-bias">对手选择偏置</a>在这里拿到完整的理论解法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>FSP 的历史频率有两个毛病。一是<strong>表达</strong>：历史频率只是动作频率，当策略本身是复杂函数时，两个完全不同策略可以产生相同频率，元信息全丢。二是<strong>收敛速度</strong>：均匀的频率平均在支撑大的博弈里走得太慢，均衡可能要的恰好是稀疏的支撑。PSRO 的做法是把问题升维再求解：维护一个策略池 \\(\\Pi=\\{\\pi_1,\\ldots,\\pi_k\\}\\)，把它们两两对打的胜率表当成一个 \\(k\\) 行 \\(k\\) 列的<strong>元博弈</strong>（meta-game），在每个玩家所处的元博弈上解均衡 \\(\\sigma\\)，得到一个池上的混合策略；然后对 \\(\\sigma\\) 解新的最优响应——训练一个能提高对 \\(\\sigma\\) 胜率的策略——把它加进池子，重复。</p><p><span class="marginnote">「元博弈」翻译成大白话：把每个已练好的策略当成一位「棋手」，再办一场棋手之间的锦标赛——这张互相克制的成绩表就是元博弈。原来在招式层面博弈，现在在「用哪些招式、按什么比例」这层再博弈一次，「元」就是高一层之意。</span></p><p>这就是 double oracle 方法的 RL 化：McMahan、Gordon 与 Blum 2003 年在对抗式规划里提出「在已选列上解小博弈、再对新列做最优响应、扩张矩阵」的循环，Lanctot 等人 2017 把「新列」的产生交给深度 RL。收敛逻辑与 FSP 同源：若最优响应不再能找到任何改进，当前池上的均衡就是全博弈的近似均衡；在此之前，每个新策略都是对当前混合的一块盲区的补丁。</p><h3 id="元博弈层面的选择" tabindex="-1">元博弈层面的选择 <a class="header-anchor" href="#元博弈层面的选择" aria-label="Permalink to &quot;元博弈层面的选择&quot;">​</a></h3><p>PSRO 是一个框架而不是一个算法，自由度全在「元博弈上解什么」：零和里解纳什（近似地，用上面的循环本身），多方或团队博弈里换 α-Rank、相关均衡或投影目标，这决定了对手池长成什么形状。Lanctot 等人 2017 的原设计还带_prior_：用元博弈上的信念初始化响应训练，让旧经验指导新对手怎么找。工程上另一条著名分支是 AlphaStar 的联赛（Vinyals 等 2019）：主智能体打池中采样的对手分布，另设两类「挖掘者」（exploiter）专门攻击主智能体或整个联赛的弱点，把「发现盲区」从循环里的一步变成专职角色——盲区挖掘被岗位化了。</p><p><span class="marginnote">元博弈矩阵每格是两个冻结策略互打的胜率，一次对打一小局都逃不掉：池大 \\(k\\) 倍，评测成本近 \\(k^2\\) 倍。PSRO 的贵不在训练单个响应，而在把池子填满之前的对打矩阵。</span></p>',10)),(o(),A(n,null,{default:e(()=>[r(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20POOL%5B%22%E7%AD%96%E7%95%A5%E6%B1%A0%20%CE%A0%22%5D%20--%3E%20MAT%5B%22%E4%B8%A4%E4%B8%A4%E5%AF%B9%E6%89%93%EF%BC%9A%E5%85%83%E5%8D%9A%E5%BC%88%E7%9F%A9%E9%98%B5%22%5D%0A%20%20MAT%20--%3E%20EQ%5B%22%E8%A7%A3%E5%85%83%E5%8D%9A%E5%BC%88%E5%9D%87%E8%A1%A1%20%CF%83%22%5D%0A%20%20EQ%20--%3E%20BR%5B%22%E8%AE%AD%E7%BB%83%E6%9C%80%E4%BC%98%E5%93%8D%E5%BA%94%20BR(%CF%83)%22%5D%0A%20%20BR%20--%3E%20Q%7B%22%E8%BF%98%E8%83%BD%E6%94%B9%E8%BF%9B%E5%90%97%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E8%83%BD%22%7C%20ADD%5B%22%E5%85%A5%E6%B1%A0%EF%BC%9A%CE%A0%20%E2%86%90%20%CE%A0%20%E2%88%AA%20BR%22%5D%0A%20%20ADD%20--%3E%20MAT%0A%20%20Q%20--%3E%7C%22%E4%B8%8D%E8%83%BD%22%7C%20OUT%5B%22%E8%BE%93%E5%87%BA%EF%BC%9A%CF%83%20%E4%B8%8E%E6%B1%A0%EF%BC%8C%E8%BF%91%E4%BC%BC%E5%85%83%E5%9D%87%E8%A1%A1%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"方法",tabindex:"-1"},[B("方法 "),a("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),E[4]||(E[4]=a("p",null,[B("本课的方法是"),a("strong",null,"元博弈循环"),B("：维护策略池，把两两对打的胜率表升格为元博弈，在其上解均衡 \\(\\sigma\\)，再对 \\(\\sigma\\) 训练最优响应入池——骨架承 double oracle，「新列」的产生交给深度 RL。方法的核心动作是升维：对手分布、收敛判据、池的多样性从三件直觉变成三个显式旋钮（分别是 \\(\\sigma\\)、响应改进量、矩阵行数）。LLM 场景的折中是冻结历史版本加均衡采样，用矩阵精度换轮次速度。")],-1)),E[5]||(E[5]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[6]||(E[6]=a("p",null,"PSRO 把「对手从哪来」变成显式对象，于是三件以前靠直觉的事变成可调的旋钮。对手分布是 \\(\\sigma\\)，不再是历史频率的副产品；收敛判据是「最优响应的改进量」，一个可测的数，替代「训练曲线看着平了」；池的多样性是元博弈的行数，替代「 checkpoints 留了几个」。机制上的代价是最后迭代问题的换形：元博弈均衡解得再准，也只是当前池上的均衡，池外盲区由响应训练负责探——若响应训练失败（RL 没学出改进），循环会误报收敛。因此工程上要给「改进量」设阈值并配独立的探查预算，不能只信循环自己的收敛宣言。",-1)),E[7]||(E[7]=a("p",null,"这张图回答的问题是：三个旋钮各自替换了哪个旧直觉，脆弱点长在哪。",-1)),(o(),A(n,null,{default:e(()=>[r(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20K1%5B%22%E6%97%8B%E9%92%AE%E4%B8%80%EF%BC%9A%E5%AF%B9%E6%89%8B%E5%88%86%E5%B8%83%20%3D%20%E5%85%83%E5%8D%9A%E5%BC%88%E5%9D%87%E8%A1%A1%20%CF%83%22%5D%20--%3E%20OLD1%5B%22%E6%9B%BF%E4%BB%A3%EF%BC%9A%E5%8E%86%E5%8F%B2%E9%A2%91%E7%8E%87%E7%9A%84%E5%89%AF%E4%BA%A7%E5%93%81%22%5D%0A%20%20K2%5B%22%E6%97%8B%E9%92%AE%E4%BA%8C%EF%BC%9A%E6%94%B6%E6%95%9B%E5%88%A4%E6%8D%AE%20%3D%20%E5%93%8D%E5%BA%94%E6%94%B9%E8%BF%9B%E9%87%8F%22%5D%20--%3E%20OLD2%5B%22%E6%9B%BF%E4%BB%A3%EF%BC%9A%E8%AE%AD%E7%BB%83%E6%9B%B2%E7%BA%BF%E7%9C%8B%E7%9D%80%E5%B9%B3%E4%BA%86%22%5D%0A%20%20K3%5B%22%E6%97%8B%E9%92%AE%E4%B8%89%EF%BC%9A%E6%B1%A0%E5%A4%9A%E6%A0%B7%E6%80%A7%20%3D%20%E7%9F%A9%E9%98%B5%E8%A1%8C%E6%95%B0%22%5D%20--%3E%20OLD3%5B%22%E6%9B%BF%E4%BB%A3%EF%BC%9Acheckpoint%20%E7%95%99%E4%BA%86%E5%87%A0%E4%B8%AA%22%5D%0A%20%20K2%20--%3E%20RISK%5B%22%E8%84%86%E5%BC%B1%E7%82%B9%EF%BC%9ARL%20%E6%B2%A1%E5%AD%A6%E5%87%BA%E6%94%B9%E8%BF%9B%E6%97%B6%E8%AF%AF%E6%8A%A5%E6%94%B6%E6%95%9B%22%5D%0A%20%20RISK%20--%3E%20GUARD%5B%22%E6%94%B9%E8%BF%9B%E9%87%8F%E9%98%88%E5%80%BC%20%2B%20%E7%8B%AC%E7%AB%8B%E6%8E%A2%E6%9F%A5%E9%A2%84%E7%AE%97%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[8]||(E[8]=t('<p>对语言模型，PSRO 的直接移植受限于元博弈矩阵的评测成本：两个 LLM 互打的「胜率」要用评测集近似，\\(k^2\\) 格每格都贵。实务的折中是冻结若干历史版本、按均衡权重采样对手做自博弈微调（SPIN 式的迭代自博弈，Chen 等 2024 的做法可视为其极简版：对上一代自身生成的答案做偏好训练），把矩阵的精度换成轮次的速度。</p><p><span class="marginnote">数字实例：池里 10 个策略，两两对打约要 45 局；池到 100 个，就涨到约 5000 局——成本按平方涨。每次对打都是两个大模型各答一遍评测集，这就是 LLM 场景宁可冻结旧版本、按均衡权重粗采样，也不把池子填满的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>PSRO 的保证落在零和或良性的元博弈上：元博弈本身是一般和时，池上解什么均衡就继承了那一层的全部争议（上一课的 PPAD 与动力学边界原样适用）。</p><p><span class="marginnote">常见误区：以为「池上解出均衡」就安全了。均衡只对池内分布有保证——好比只在自家车队内部选出了最强阵型，遇上外面没见过的跑法照样输。池外盲区要靠响应训练去探，池子本身从不承诺覆盖全世界。</span> 响应训练是最脆弱的一环——「oracle 求不出」与「求出了但训练没收敛」在循环里不可区分，需要单独诊断。对手池还引入一个新风险：池上的均衡可能过拟合到池内对手的分布，对池外策略（或真实用户）没有保证；「对手课程为什么永远做不完」是下一课的主题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PSRO 维护策略池，把对打胜率表当元博弈、在其上解均衡，再对均衡解最优响应入池。</li><li>骨架来自 double oracle（McMahan 等 2003），RL 化来自 Lanctot 等 2017；AlphaStar 联赛把盲区挖掘岗位化。</li><li>对手分布、收敛判据、池多样性从直觉变成三个可调对象；代价是 \\(k^2\\) 的评测矩阵。</li><li>最脆弱处是响应 oracle：训练失败与真收敛在循环内不可区分，须设改进量阈值。</li><li>LLM 上常以冻结历史版本加均衡采样折中，换取矩阵成本。</li><li>出处：McMahan、Gordon 与 Blum 2003；Lanctot 等 2017；Vinyals 等 2019；Chen 等 2024（SPIN）。</li></ul>',7))])}const g=s(d,[["render",D]]);export{S as __pageData,g as default};
